def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = max(counts, key=counts.get)
    marker = next(v for v in counts if v != bg)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    top, bottom = min(r for r, c in pts), max(r for r, c in pts)
    left, right = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    def paint(r, c):
        if out[r][c] == bg:
            out[r][c] = 2
    # Draw the outer bounding frame.
    for c in range(left, right + 1):
        paint(top, c)
        paint(bottom, c)
    for r in range(top, bottom + 1):
        paint(r, left)
        paint(r, right)
    # Join interior lines only when at least two markers lie strictly inside
    # the frame; boundary markers alone do not define crossbars.
    for r in range(top + 1, bottom):
        cs = [c for c in range(left + 1, right) if grid[r][c] == marker]
        if len(cs) >= 2:
            for c in range(left, right + 1):
                paint(r, c)
    for c in range(left + 1, right):
        rs = [r for r in range(top + 1, bottom) if grid[r][c] == marker]
        if len(rs) >= 2:
            for r in range(top, bottom + 1):
                paint(r, c)
    return out

